import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.DaGSOal_.js";const p=JSON.parse('{"title":"F","description":"","frontmatter":{},"headers":[],"relativePath":"glossaire-a-z/f.md","filePath":"glossaire-a-z/f.md"}'),o={name:"glossaire-a-z/f.md"};function s(i,e,l,u,d,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="f" tabindex="-1">F <a class="header-anchor" href="#f" aria-label="Permalink to &quot;F&quot;">​</a></h1><h2 id="fatf-travel-rule-fr-regle-de-voyage-du-gafi" tabindex="-1">FATF Travel Rule (fr : Règle de voyage du GAFI) <a class="header-anchor" href="#fatf-travel-rule-fr-regle-de-voyage-du-gafi" aria-label="Permalink to &quot;FATF Travel Rule (fr : Règle de voyage du GAFI)&quot;">​</a></h2><p>La règle de voyage du GAFI est une exigence mondiale de lutte contre le blanchiment d’argent émise par le Groupe d’action financière (GAFI). Elle oblige les prestataires de services sur actifs virtuels (PSAV), tels que les plateformes d’échange et les dépositaires, à collecter et à partager des informations permettant d’identifier l’expéditeur et le destinataire lors de transferts d’actifs numériques dépassant certains seuils. Toutefois, cette règle ne concerne pas uniquement les actifs numériques, mais s’applique à tous les intermédiaires financiers. Elle trouve son origine dans les réglementations traditionnelles relatives aux virements bancaires.</p><p>→ <a href="https://www.fatf-gafi.org/" target="_blank" rel="noreferrer">Groupe d’action financière (GAFI) — Site officiel</a></p><h2 id="faucet-fr-robinet-de-distribution-de-jetons" tabindex="-1">Faucet (fr : Robinet de distribution de jetons) <a class="header-anchor" href="#faucet-fr-robinet-de-distribution-de-jetons" aria-label="Permalink to &quot;Faucet (fr : Robinet de distribution de jetons)&quot;">​</a></h2><p>Un faucet est un service qui fournit aux utilisateurs de petites quantités de jetons, généralement gratuitement, afin qu’ils puissent tester un réseau blockchain ou expérimenter avec celui-ci. Sur Cardano, les faucets servent principalement à distribuer de l’ada de test (<em>tADA</em>) sur les réseaux de test, permettant aux développeurs et aux utilisateurs d’essayer des transactions, des contrats intelligents ou des applications sans utiliser de véritables ada.</p><p>→ <a href="https://docs.cardano.org/cardano-testnet/tools/faucet/" target="_blank" rel="noreferrer">Testnets Faucet — Cardano Docs</a></p><h2 id="fee-fr-frais-de-transaction" tabindex="-1">Fee (fr : Frais de transaction) <a class="header-anchor" href="#fee-fr-frais-de-transaction" aria-label="Permalink to &quot;Fee (fr : Frais de transaction)&quot;">​</a></h2><p>Une petite quantité de jetons payée pour traiter une transaction sur une blockchain. Sur Cardano, les frais de transaction sont nécessaires pour prévenir le spam, rémunérer les producteurs de blocs et contribuer à la trésorerie du réseau. Leur montant exact est déterminé par les paramètres du protocole et la taille de la transaction.</p><p>→ <a href="https://developers.cardano.org/docs/learn/core-concepts/fees/" target="_blank" rel="noreferrer">Transaction Fees — Cardano Developer Portal</a></p><h2 id="fork-fr-fourche" tabindex="-1">Fork (fr : Fourche) <a class="header-anchor" href="#fork-fr-fourche" aria-label="Permalink to &quot;Fork (fr : Fourche)&quot;">​</a></h2><p>Une modification du protocole d’une blockchain qui entraîne une divergence par rapport aux règles existantes. Les forks peuvent être des <em>soft forks</em>, qui introduisent des mises à jour rétrocompatibles, ou des <em>hard forks</em>, qui nécessitent que tous les participants effectuent une mise à niveau pour rester sur la même chaîne.</p><p>→ <a href="https://docs.cardano.org/about-cardano/evolution/about-hard-forks" target="_blank" rel="noreferrer">About hard forks — Cardano Docs</a></p><h2 id="full-node-fr-nœud-complet" tabindex="-1">Full Node (fr : Nœud complet) <a class="header-anchor" href="#full-node-fr-nœud-complet" aria-label="Permalink to &quot;Full Node (fr : Nœud complet)&quot;">​</a></h2><p>Un logiciel qui télécharge et vérifie l’intégralité de la blockchain, c’est-à-dire le registre complet depuis le premier bloc, en s’assurant que toutes les transactions et tous les blocs respectent les règles du protocole. Sur Cardano, l’exploitation d’un nœud complet actif contribue à la décentralisation et permet aux utilisateurs de valider le registre de manière indépendante, sans dépendre de tiers.</p><h2 id="fungible-token-fr-jeton-fongible" tabindex="-1">Fungible Token (fr : Jeton fongible) <a class="header-anchor" href="#fungible-token-fr-jeton-fongible" aria-label="Permalink to &quot;Fungible Token (fr : Jeton fongible)&quot;">​</a></h2><p>Une unité de valeur numérique interchangeable avec toute autre unité du même type et de la même dénomination. Sur Cardano, l’ada et les autres jetons natifs peuvent être considérés comme fongibles lorsque chaque unité d’un jeton est fonctionnellement identique.</p><p>→ <a href="https://docs.cardano.org/native-tokens/getting-started/" target="_blank" rel="noreferrer">Mint a Fungible Token — Cardano Docs</a></p>',18)])])}const m=t(o,[["render",s]]);export{p as __pageData,m as default};
